using System.Text.Json;
using Avalonia.Controls;
using LtcPlayer.App;
namespace LtcPlayer.Avalonia;
public static class LtcSettingsVerification
{
 public static async Task RunAsync(MainWindow w,string folder)
 {
  Directory.CreateDirectory(folder);var results=new List<object>();bool failed=false;int receiving=0;var display=VideoRenderer.Displays().First(d=>d.Primary!=0);string file=Program.Option("--settings")!;
  InputSettings Saved()=>InputSettings.Load(file);
  void Check(bool ok,string why){if(!ok)throw new IOException(why);}
  async Task Until(Func<bool> condition){double end=MasterClock.Timestamp()+12;while(!condition()){if(MasterClock.Timestamp()>end)throw new TimeoutException(JsonSerializer.Serialize(new{w.Preview.Snapshot,w.LatestObservation,w.Coordinator.Audio}));await Task.Delay(10);}}
  async Task Test(string name,Func<Task> body){try{await body();results.Add(new{test=name,status="PASS"});}catch(Exception e){failed=true;results.Add(new{test=name,status="FAIL",detail=e.ToString()});}File.WriteAllText(Path.Combine(folder,"results.json"),JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));}
  Task Apply(InputSettings s)=>w.ApplySettingsAsync(new(s,display));
  var row=new CueRow{FilePath=Path.Combine(Program.Option("--fixtures")!,"hap-sync-30s.mov")};
  bool Synchronized(Guid? previous=null){
   var session=w.SynchronizationSession;var observation=w.Coordinator.Observation;
   var head=w.Coordinator.ReadAudioPlayhead();var audio=w.Coordinator.Audio;
   // The UI may still expose the preceding run's observation while the new
   // session is awaiting ownership. Require the current run and fresh audio.
   return session.HasValue&&session!=previous&&observation is{FramePts:>0}&&observation.CueId==row.CueId&&
    head.SessionId==session&&head.CueId==row.CueId&&audio.State==SharedAudioState.Playing&&
    audio.CueId==row.CueId&&audio.HostSeconds>=observation.TargetHostSeconds;
  }
  Task Source(MasterClock clock,CancellationToken t)=>Task.Run(async()=>{double start=MasterClock.Timestamp();while(!t.IsCancellationRequested){if(Volatile.Read(ref receiving)!=0){int f=25+(int)((MasterClock.Timestamp()-start)*25)%400;clock.Accept(new TcFrame{Seconds=f/25,Frame=f%25},MasterClock.Timestamp());}await Task.Delay(20,t);}},t);
  try{
   await Test("clock policy update preserves WAITING and rejects invalid values atomically",()=>{var c=new MasterClock(TimecodeRate.Modes[1]);c.UpdatePolicy(.2,4);bool bad=false;try{c.UpdatePolicy(double.NaN,2);}catch(ArgumentOutOfRangeException){bad=true;}Check(bad&&c.Read(10).State==SyncState.WAITING&&c.FreewheelSeconds==.2&&c.ResyncFrames==4,"invalid policy mutated state");return Task.CompletedTask;});
   await Test("new freewheel cap starts with next actual LTC frame",()=>{var c=new MasterClock(TimecodeRate.Modes[1],.1);c.Accept(new TcFrame(),10);c.UpdatePolicy(.5,2);Check(c.Read(10.2).State==SyncState.LOST,"policy applied retrospectively");c.Accept(new TcFrame{Frame=1},10.04);Check(c.Read(10.3).State==SyncState.FREEWHEEL&&Math.Abs(c.Read(11).Seconds-.58)<1e-9,"next frame did not adopt cap");return Task.CompletedTask;});
   await Test("policy extension cannot revive LOST or alter held target generation",()=>{var c=new MasterClock(TimecodeRate.Modes[1],.1);c.Accept(new TcFrame(),10);var before=c.Read(11);c.UpdatePolicy(10,20);Check(c.Read(11)==before,"LOST changed on extension");return Task.CompletedTask;});
   await Test("policy reduction leaves current FREEWHEEL trajectory until next frame",()=>{var c=new MasterClock(TimecodeRate.Modes[1],.5);c.Accept(new TcFrame(),10);var before=c.Read(10.2);c.UpdatePolicy(0,2);Check(before.State==SyncState.FREEWHEEL&&c.Read(10.2)==before,"FREEWHEEL clamped retrospectively");return Task.CompletedTask;});
   await Test("new resync threshold applies to next packet but old loss gap remains a discontinuity",()=>{var c=new MasterClock(TimecodeRate.Modes[1],.1);c.Accept(new TcFrame(),10);c.UpdatePolicy(2,20);c.Accept(new TcFrame{Frame=4},10.04);Check(c.Read(10.04).Generation==0,"new threshold ignored");c.Accept(new TcFrame{Seconds=1},11);Check(c.Read(11).Generation==0,"new cap ignored");var d=new MasterClock(TimecodeRate.Modes[1],.1);d.Accept(new TcFrame(),10);d.UpdatePolicy(2,100);d.Accept(new TcFrame{Seconds=1},11);Check(d.Read(11).Generation==1,"old LOST gap erased");return Task.CompletedTask;});
   await Test("policy changes cannot clear input ERROR",()=>{var c=new MasterClock(TimecodeRate.Modes[1]);c.Accept(new TcFrame(),10);c.Fault();var before=c.Read(11);c.UpdatePolicy(2,5);Check(c.Read(11)==before,"ERROR cleared without input");c.Accept(new TcFrame{Frame=1},11);Check(c.Read(11).State==SyncState.RESYNC&&c.Read(11).Generation==1,"real input did not recover ERROR");return Task.CompletedTask;});
   await Apply(new(Rate:"25"));await w.Monitor.ConfigureAsync(Saved(),Source);await ShowProgramService.RefreshAsync(row,CancellationToken.None);w.Editor.Add(row);await w.SetSharedAudioAsync(true,silenceForVerification:true);await w.PlayCueForTestAsync(row);await w.ArmAsync();await Until(()=>w.Coordinator.Audio.State==SharedAudioState.Playing);
   await Test("output and audio connected permit LTC settings while hardware outputs remain locked",async()=>{
    var d=new SettingsDialog(Saved(),display,true,true,w.Monitor);var shown=d.ShowDialog<SettingsResult?>(w);try{await Task.Delay(50);Check(d.OffsetInput.IsEffectivelyEnabled&&d.FreewheelInput.IsEffectivelyEnabled&&d.ResyncInput.IsEffectivelyEnabled&&d.InputRefreshButton.IsEffectivelyEnabled&&!d.ModeSelector.IsEffectivelyEnabled&&!d.AudioOutputSelector.IsEffectivelyEnabled,"wrong enabled controls");d.OffsetInput.Text="1";Check(d.ApplyButton.IsEnabled,"LTC change cannot apply");}finally{d.Close(null);await shown;}
   });
   await Test("manual policy changes retain input video audio and cache sessions",async()=>{
    var clock=w.Monitor.Clock;int starts=w.Monitor.Starts,preps=w.Coordinator.Audio.PreparationStarts;var video=w.Preview.PlaybackSessionId;var sink=w.Coordinator.Audio.SinkSession;long builds=w.Preview.IndexCache.Builds;
    await Apply(Saved() with{Freewheel=.25,Resync=3});Check(ReferenceEquals(clock,w.Monitor.Clock)&&w.Monitor.Starts==starts&&w.Preview.PlaybackSessionId==video&&w.Coordinator.Audio.SinkSession==sink&&w.Coordinator.Audio.PreparationStarts==preps&&w.Preview.IndexCache.Builds==builds,"policy rebuilt playback resources");
   });
   await Test("manual offset changes do not seek or reopen input",async()=>{var video=w.Preview.PlaybackSessionId;var clock=w.Monitor.Clock;double at=w.Preview.Snapshot.Position;await Apply(Saved() with{Offset=25});await Task.Delay(120);Check(w.Preview.PlaybackSessionId==video&&ReferenceEquals(clock,w.Monitor.Clock)&&w.Preview.Snapshot.Position>at,"manual offset disturbed playback");});
   Volatile.Write(ref receiving,1);await Until(()=>Synchronized());
   await Test("live policy changes keep synchronization and audio sessions",async()=>{var sync=w.SynchronizationSession;var clock=w.Monitor.Clock;int starts=w.Monitor.Starts,preps=w.Coordinator.Audio.PreparationStarts;var sink=w.Coordinator.Audio.SinkSession;await Apply(Saved() with{Freewheel=.3,Resync=5});await Task.Delay(150);Check(w.SynchronizationSession==sync&&ReferenceEquals(clock,w.Monitor.Clock)&&w.Monitor.Starts==starts&&w.Coordinator.Audio.SinkSession==sink&&w.Coordinator.Audio.PreparationStarts==preps,JsonSerializer.Serialize(new{message="live policy restarted synchronization",sync,actual=w.SynchronizationSession,starts,actualStarts=w.Monitor.Starts,preps,actualPreps=w.Coordinator.Audio.PreparationStarts,sink,actualSink=w.Coordinator.Audio.SinkSession}));});
   await Test("live offset reseeks synchronization without reopening input or audio output",async()=>{
    var sync=w.SynchronizationSession;var clock=w.Monitor.Clock;var sink=w.Coordinator.Audio.SinkSession;var canvas=w.Surface.Canvas.SessionId;int starts=w.Monitor.Starts;
    await Apply(Saved() with{Offset=-10});await Until(()=>Synchronized(sync));
    var head=w.Coordinator.ReadAudioPlayhead();var current=clock.Read();
    var evidence=new{PreviousSession=sync,Session=w.SynchronizationSession,SameClock=ReferenceEquals(clock,w.Monitor.Clock),StartsBefore=starts,StartsAfter=w.Monitor.Starts,SinkBefore=sink,SinkAfter=w.Coordinator.Audio.SinkSession,CanvasBefore=canvas,CanvasAfter=w.Surface.Canvas.SessionId,Head=head,Clock=current,ExpectedPosition=current.Seconds-.4};
    File.WriteAllText(Path.Combine(folder,"offset-transition.json"),JsonSerializer.Serialize(evidence,new JsonSerializerOptions{WriteIndented=true}));
    Check(evidence.SameClock&&evidence.StartsAfter==starts&&evidence.SinkAfter==sink&&evidence.CanvasAfter==canvas&&Math.Abs(head.Position-evidence.ExpectedPosition)<.15,JsonSerializer.Serialize(evidence));
   });
   Volatile.Write(ref receiving,0);await Until(()=>w.Monitor.Clock.Read().State==SyncState.LOST);await Task.Delay(150);
   await Test("extending freewheel does not revive LOST signal or move held image",async()=>{var before=w.Monitor.Clock.Read();var pixels=w.Surface.Canvas.Readback();var sync=w.SynchronizationSession;await Apply(Saved() with{Freewheel=2});await Task.Delay(150);var after=w.Monitor.Clock.Read();Check(after.State==SyncState.LOST&&after.Seconds==before.Seconds&&after.Generation==before.Generation&&sync==w.SynchronizationSession&&pixels.AsSpan().SequenceEqual(w.Surface.Canvas.Readback())&&!w.Coordinator.ReadAudioPlayhead().Advancing,"old signal revived");});
   await Test("LOST offset preserves hold and applies on actual LTC resumption",async()=>{var sync=w.SynchronizationSession;var pixels=w.Surface.Canvas.Readback();await Apply(Saved() with{Offset=50,Freewheel=.1});await Task.Delay(120);Check(sync==w.SynchronizationSession&&pixels.AsSpan().SequenceEqual(w.Surface.Canvas.Readback()),"offset altered LOST hold");Volatile.Write(ref receiving,1);await Until(()=>Synchronized(sync));Check(Math.Abs(w.Coordinator.ReadAudioPlayhead().Position-(w.Monitor.Clock.Read().Seconds+2))<.15,"resumption used old offset");});
   await Test("failed settings persistence leaves clock policy offset and run untouched",async()=>{string before=File.ReadAllText(file);var sync=w.SynchronizationSession;var clock=w.Monitor.Clock;bool rejected=false;using(var locked=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){try{await Apply(Saved() with{Offset=100,Freewheel=9,Resync=10});}catch(Exception e)when(e is IOException or UnauthorizedAccessException){rejected=true;}}Check(rejected&&File.ReadAllText(file)==before&&ReferenceEquals(clock,w.Monitor.Clock)&&clock.FreewheelSeconds==.1&&clock.ResyncFrames==5&&sync==w.SynchronizationSession,"failed save applied live settings");});
   Volatile.Write(ref receiving,0);await Until(()=>w.Monitor.Clock.Read().State==SyncState.LOST);await w.PlayCueForTestAsync(row);await Until(()=>w.Preview.Snapshot.State==PreviewState.Playing);
   Action<float,string>? stale=null;int opens=0;w.Monitor.RunInputForTest=(s,c,status,ready,t)=>{opens++;stale??=status;ready(null);return Task.Delay(Timeout.Infinite,t);};
   await Test("input rate switch without LTC leaves manual video and shared audio running",async()=>{var video=w.Preview.PlaybackSessionId;var canvas=w.Surface.Canvas.SessionId;var sink=w.Coordinator.Audio.SinkSession;await Apply(Saved() with{DeviceId="fake-a",Rate="30"});await Task.Delay(80);Check(opens==1&&w.Monitor.Clock.Read().State==SyncState.WAITING&&video==w.Preview.PlaybackSessionId&&canvas==w.Surface.Canvas.SessionId&&sink==w.Coordinator.Audio.SinkSession&&w.Preview.Snapshot.State==PreviewState.Playing,"input switch disturbed manual playback");});
   await Test("obsolete input callbacks cannot overwrite current input meter or status",async()=>{await Apply(Saved() with{Channel=1});stale!(1,"obsolete");Check(w.Monitor.Status!="obsolete"&&w.Monitor.Level==0,"obsolete status leaked");});
   await Test("input readiness requires opening and decoder initialization but no LTC",async()=>{var gate=new TaskCompletionSource();w.Monitor.RunInputForTest=(s,c,status,ready,t)=>Task.Run(async()=>{await gate.Task.WaitAsync(t);ready(null);await Task.Delay(Timeout.Infinite,t);},t);string before=File.ReadAllText(file);var apply=Apply(Saved() with{DeviceId="fake-b"});await Task.Delay(100);Check(!apply.IsCompleted&&File.ReadAllText(file)==before,"settings committed before ready");gate.SetResult();await apply;Check(Saved().DeviceId=="fake-b"&&w.Monitor.Clock.Read().State==SyncState.WAITING,"missing LTC rejected ready input");});
   await Test("input opening failure restores original clock input and saved settings",async()=>{var clock=w.Monitor.Clock;string before=File.ReadAllText(file);bool rejected=false;w.Monitor.RunInputForTest=(s,c,status,ready,t)=>{ready(s.DeviceId=="bad"?new IOException("synthetic opening failure"):null);return Task.Delay(Timeout.Infinite,t);};try{await Apply(Saved() with{DeviceId="bad"});}catch(IOException){rejected=true;}Check(rejected&&ReferenceEquals(clock,w.Monitor.Clock)&&File.ReadAllText(file)==before&&w.IsOutputActive,"input rollback failed");});
   await Test("save failure after input readiness restores original input and settings",async()=>{var clock=w.Monitor.Clock;string before=File.ReadAllText(file);bool rejected=false;using(var locked=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){try{await Apply(Saved() with{Channel=0});}catch(Exception e)when(e is IOException or UnauthorizedAccessException){rejected=true;}}Check(rejected&&ReferenceEquals(clock,w.Monitor.Clock)&&File.ReadAllText(file)==before&&w.IsOutputActive,"post-open save rollback failed");});
   await Test("synchronized input switch releases old video to black and silence without detaching output",async()=>{var c=w.Monitor.Clock;c.Accept(new TcFrame{Seconds=2},MasterClock.Timestamp());await Until(()=>w.Coordinator.OwnsSurface&&w.LatestObservation?.FramePts>0);var canvas=w.Surface.Canvas.SessionId;await Apply(Saved() with{Channel=0});await Until(()=>!w.Coordinator.OwnsSurface&&w.Coordinator.Audio.State==SharedAudioState.Waiting);Check(w.IsOutputActive&&canvas==w.Surface.Canvas.SessionId&&w.Preview.LoadedPath==""&&w.Surface.Canvas.Readback().Where((_,i)=>i%4!=3).All(v=>v==0),"old sync source survived or output detached");});
   await Test("closing input monitor cancels pending readiness and ignores late callbacks",async()=>{var m=new LtcMonitorService();Action<float,string>? late=null;var entered=new TaskCompletionSource();m.RunInputForTest=(s,c,status,ready,t)=>{late=status;entered.SetResult();return Task.Delay(Timeout.Infinite,t);};var configure=m.ConfigureAsync(new(DeviceId:"pending"),requireReady:true);await entered.Task;await m.DisposeAsync();bool cancelled=false;try{await configure;}catch(OperationCanceledException){cancelled=true;}late!(1,"late");Check(cancelled&&m.Status!="late","close retained input worker or published late callback");});
   await Test("failed input rollback reports both failures and keeps output with explicit ERROR",async()=>{string before=File.ReadAllText(file);w.Monitor.RunInputForTest=(s,c,status,ready,t)=>{ready(new IOException("synthetic open and rollback failure"));return Task.Delay(Timeout.Infinite,t);};bool rejected=false;try{await Apply(Saved() with{DeviceId="broken"});}catch(AggregateException e){rejected=e.InnerExceptions.Count==2;}Check(rejected&&File.ReadAllText(file)==before&&w.Monitor.Clock.Read().State==SyncState.ERROR&&w.IsOutputActive,"rollback failure hidden or saved settings changed");});
  }catch(Exception e){failed=true;File.WriteAllText(Path.Combine(folder,"fatal.txt"),e.ToString());}
  finally{w.Monitor.RunInputForTest=null;Volatile.Write(ref receiving,0);await w.DisarmAsync();await w.Coordinator.DisposeAsync();await w.Preview.DisposeAsync();await w.Monitor.DisposeAsync();MainWindow.Shutdown(failed?1:0);}
 }
}
